<?php
require_once __DIR__.'/includes/survey_app.php';[$role,$staff]=sv_staff();
$sql='SELECT a.id,a.trainee_id,a.theme_id,a.completed_at,a.corrected_at,a.total_score,a.maximum_score,t.first_name,t.last_name,d.title FROM attempts a JOIN survey_attempt_data x ON x.attempt_id=a.id JOIN survey_definitions d ON d.id=x.survey_definition_id JOIN trainees t ON t.id=a.trainee_id';$params=[];
if($role==='professor'){$sql.=' WHERE EXISTS(SELECT 1 FROM professor_content_assignments p WHERE p.professor_id=? AND p.theme_id=a.theme_id AND p.chapter_id IS NULL) AND EXISTS(SELECT 1 FROM professor_trainee_assignments p WHERE p.professor_id=? AND p.trainee_id=a.trainee_id)';$params=[$staff,$staff];}
$s=$pdo->prepare($sql.' ORDER BY a.id DESC LIMIT 200');$s->execute($params);
?><!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Résultats et corrections</title><link rel="stylesheet" href="assets/survey/app.css"><main><a href="<?= $role ?>/index.php">Retour</a> · <a href="survey_creator.php">Créer un questionnaire</a><h1>Résultats et corrections</h1><table><tr><th>Stagiaire</th><th>Questionnaire</th><th>Note</th><th>État</th></tr><?php foreach($s as $r):?><tr><td><?= qp_h($r['first_name'].' '.$r['last_name']) ?></td><td><a href="survey_result.php?id=<?= (int)$r['id'] ?>"><?= qp_h($r['title']) ?></a></td><td><?= qp_h($r['total_score']) ?> / <?= qp_h($r['maximum_score']) ?></td><td><?= $r['corrected_at']?'Corrigé':'À corriger' ?></td></tr><?php endforeach;?></table><p>Affichage des 200 dernières passations autorisées.</p></main></html>
